TEST = r'''<script>
(function(){
  var R={greski:[],info:{}};
  function tvrdi(u,p){ if(!u) R.greski.push(p); }
  try{
    var T=window.__test;
    tvrdi(!!T,"nema window.__test");
    T.resetiraj();
    var s=T.daj();
    R.info.pocetniPari=s.parichnik;

    // 1) sadenje
    T.zasadiSemka(0,"skopsko");
    tvrdi(!!s.lei[0].rastenie,"sadenjeto ne sozdade rastenie");
    tvrdi(s.semki.skopsko===0,"semkata ne e potrosena");

    // 2) rast so griza + invarijanti
    var fazi=[],tikovi=0,ok=true;
    while(tikovi<4000){
      T.tikni(); tikovi++;
      var r=s.lei[0].rastenie; if(!r) break;
      if(!(r.voda>=0&&r.voda<=100)) ok=false;
      if(!(r.zdravje>=0&&r.zdravje<=100)) ok=false;
      if(!(r.hraniva>=0&&r.hraniva<=100)) ok=false;
      if(!isFinite(s.parichnik)||s.parichnik<0) ok=false;
      if(!fazi.length||fazi[fazi.length-1]!==r.faza) fazi.push(r.faza);
      if(r.voda<45) T.polej(0);
      if(r.hraniva<45&&s.parichnik>=100) T.nahrani(0);
      if(r.stetnik==="azot"&&s.parichnik>=100) T.nahrani(0);
      else if(r.stetnik&&s.parichnik>=250) T.tretiraj(0);
      if(r.faza==="ZRELO") break;
    }
    R.info.tikoviDoZrelost=tikovi;
    R.info.sekundiDoZrelost=+(tikovi*0.25).toFixed(1);
    R.info.fazi=fazi;
    tvrdi(ok,"prekrsena invarijanta 0-100 ili pari");
    tvrdi(fazi.join(">")==="NIKNENJE>VEGETACIJA>CVETANJE>ZRELO","pogresen redosled: "+fazi.join(">"));

    // 3) berba
    T.oberi(0);
    tvrdi(s.lei[0].rastenie===null,"lejata ne e ispraznета po berba");
    tvrdi(s.sushara.length===1,"nema serija vo sushara");
    R.info.gramaVlazno=Math.round(s.sushara[0].gramaVlazno);

    // 4) susenje do idealen prozorec
    var z=0;
    while(Math.floor(s.sushara[0].denovi)<10&&z<600){ T.tikni(); z++; }
    R.info.denoviSusenje=Math.floor(s.sushara[0].denovi);
    T.zavrsiSushenje(s.sushara[0].id);
    tvrdi(s.sushara.length===0,"susharata ne e ispraznета");
    tvrdi(s.magacin.length===1,"nema proizvod vo magacin");
    var p=s.magacin[0];
    R.info.grama=Math.round(p.grama); R.info.kvalitet=Math.round(p.kvalitet); R.info.ocenka=p.ocenka;
    tvrdi(isFinite(p.grama)&&p.grama>0,"prinos ne e pozitiven broj");
    tvrdi(p.kvalitet>=0&&p.kvalitet<=100,"kvalitet nadvor od 0-100");

    // 5) laboratorija
    var pl=s.parichnik;
    T.testirajVoLaboratorija(p.id);
    tvrdi(s.magacin[0].testirano===true,"lab analiza ne pomina");
    tvrdi(Math.abs((pl-s.parichnik)-400)<1e-6,"laboratorijata ne naplati tocno 400");
    R.info.thc=s.magacin[0].thc;
    tvrdi(isFinite(s.magacin[0].thc),"THC ne e broj");

    // 6) prodazba
    var pp=s.parichnik;
    T.prodaj(s.magacin[0].id);
    tvrdi(s.magacin.length===0,"magacinot ne e ispraznет");
    tvrdi(s.parichnik>pp,"prodazbata ne donese pari");
    tvrdi(isFinite(s.parichnik),"parite stanaa NaN");
    R.info.zarabotka=Math.round(s.parichnik-pp);
    R.info.krajniPari=Math.round(s.parichnik);
    R.info.nivo=s.nivo;

    // 7) sejv / vcitaj
    var imaStorage=false;
    try{ localStorage.setItem("__t","1"); localStorage.removeItem("__t"); imaStorage=true; }catch(e){}
    R.info.imaStorage=imaStorage;
    if(imaStorage){
      T.zachuvaj();
      tvrdi(T.vchitaj()===true,"vcituvanjeto ne uspea");
      tvrdi(isFinite(T.daj().parichnik),"po vcituvanje parite ne se broj");

      // 8) osteten / zlonameren sejv
      localStorage.setItem("zelena-imperija-sejv","{ ova ne e JSON");
      tvrdi(T.vchitaj()===false,"osteten sejv ne bese odbien");
      localStorage.setItem("zelena-imperija-sejv",JSON.stringify({s:{verzija:999}}));
      tvrdi(T.vchitaj()===false,"stara verzija ne bese odbiena");
      localStorage.setItem("zelena-imperija-sejv",JSON.stringify({s:{verzija:1,parichnik:"napad",
        lei:"ne e niza",brojLei:9999,lampa:77,
        magacin:[{sorta:"nepoznata",grama:"x",ocenkaMult:1}],
        semki:{nepoznata:5,skopsko:"x"},pazar:{skopsko:9999}}}));
      T.vchitaj();
      var d=T.daj();
      tvrdi(isFinite(d.parichnik),"zlonameren sejv vnese NaN vo parite");
      tvrdi(d.magacin.length===0,"nepoznata sorta prezivea vo magacin");
      tvrdi(d.brojLei<=12,"brojLei ne e ogranicen");
      tvrdi(d.lampa<=3,"lampa ne e ogranicena");
      tvrdi(!("nepoznata" in d.semki),"nepoznata semka prezivea");
      tvrdi(d.pazar.skopsko<=1.35,"pazarot ne e ogranicen");
      R.info.otporenNaOsteten=true;
      localStorage.removeItem("zelena-imperija-sejv");
    }

    // 9) granici na kvalitetot
    var q0=T.presmetajKvalitet(0,0,0,0,0), q1=T.presmetajKvalitet(100,1,1,14,0), qn=T.presmetajKvalitet(100,1,1,14,999);
    tvrdi(q0>=0&&q1<=100&&qn>=0,"kvalitetot izleguva od 0-100");
    R.info.kvalitetMin=Math.round(q0); R.info.kvalitetMax=Math.round(q1); R.info.kvalitetSoStetnici=Math.round(qn);

    // 10) tocnost na susenje — sekoj granicen den pokrien
    R.info.tocnost=[0,7,8,9,12,13,16,17,40].map(function(d){return d+":"+T.tochnostOdSushenje(d,false);}).join(" ");
    R.info.tocnostSoSushara=[7,8,14,15,18,19].map(function(d){return d+":"+T.tochnostOdSushenje(d,true);}).join(" ");

    // 11) ekonomija — nema besplatni pari
    var pre=T.daj().parichnik;
    T.nahrani(0); T.polej(0); T.tretiraj(0);
    tvrdi(T.daj().parichnik<=pre,"akcija na prazna leja dade pari");
  }catch(e){
    R.greski.push("ISKLUCOK: "+(e&&e.message)+" | "+(e&&e.stack?String(e.stack).split("\n")[1]:""));
  }
  R.konzola=(window.__greski||[]).slice(0,10);
  document.title="REZ"+JSON.stringify(R)+"ZER";
})();
</script>'''

html = open(GAME, encoding="utf-8").read()
html = html.replace('<meta charset="utf-8">', '<meta charset="utf-8">'+RANO, 1)
html = html.replace('</body>', TEST+'\n</body>', 1)
open(os.path.join(OUT,"proba.html"),"w",encoding="utf-8").write(html)

srv = subprocess.Popen(["python3","-m","http.server","8899","--bind","127.0.0.1","--directory",OUT],
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
try:
    time.sleep(1.2)
    r = subprocess.run([BIN,"--headless=new","--no-sandbox","--disable-gpu","--disable-dev-shm-usage",
                        "--virtual-time-budget=4000","--dump-dom","http://127.0.0.1:8899/proba.html"],
                       capture_output=True, text=True, timeout=120)
    m = re.search(r"REZ(\{.*?\})ZER", r.stdout, re.S)
    if m:
        import json
        d = json.loads(m.group(1))
        print("\n=== GRESKI ===")
        print("\n".join(d["greski"]) if d["greski"] else "  (nema — site proverki pominaa)")
        print("\n=== KONZOLA ===")
        print("\n".join(d.get("konzola") or []) or "  (cisto)")
        print("\n=== INFO ===")
        for k,v in d["info"].items(): print(f"  {k} = {v}")
    else:
        print("NEMA REZULTAT vo DOM. stderr:", r.stderr[-2500:])
finally:
    srv.terminate(); srv.wait(timeout=10)
