808	const lejaJazli = [];   // трајни DOM јазли, се менуваат на место
809	// На кој дел од височината на стеблото седи секој пар лисја (одоздола нагоре).
810	const FRAKCII_LISJA = [0.30, 0.58, 0.84];
811	
812	/** Растението е чист SVG — растот е само трансформација, без слики. */
813	function svgRastenie(){
814	  const list = "M0,0 C-3.2,-11 -3.4,-26 0,-38 C3.4,-26 3.2,-11 0,0 Z";
815	  const par = (y, skala) => `
816	    <g class="par-lisja" data-y="${y}" style="transform:translate(50px,${y}px) scale(0)">
817	      ${[-72,-46,-22,0,22,46,72].map(a =>
818	        `<path d="${list}" transform="rotate(${a}) scale(${skala})"/>`).join("")}
819	    </g>`;
820	  return `<svg viewBox="0 0 100 120" preserveAspectRatio="xMidYMax meet" aria-hidden="true">
821	    <g class="rastenie-boja" fill="#4ade80">
822	      <rect class="steblo" x="48.6" y="118" width="2.8" height="0" rx="1.4"/>
823	      ${par(96, 0.55)}${par(74, 0.72)}${par(52, 0.62)}
824	      <g class="pupki" opacity="0" fill="#a3e635">
825	        <ellipse cx="50" cy="38" rx="6.5" ry="11"/>
826	        <ellipse cx="41" cy="52" rx="4.6" ry="8" opacity=".85"/>
827	        <ellipse cx="59" cy="52" rx="4.6" ry="8" opacity=".85"/>
828	      </g>
829	    </g></svg>`;
830	}
831	
832	function izgradiLei(){
833	  const kutija = document.getElementById("lei");
834	  kutija.innerHTML = "";
835	  lejaJazli.length = 0;
836	
837	  for (let i = 0; i < KONFIG.MAX_LEI; i++){
838	    const el = document.createElement("div");
839	    el.className = "leja";
840	    el.innerHTML = `
841	      <div class="leja-glava">
842	        <span class="leja-br">Леја ${i + 1}</span>
843	        <span class="leja-faza"></span>
844	      </div>
845	      <div class="scena">
846	        ${svgRastenie()}
847	        <span class="znak-sorta"></span>
848	        <span class="znak-stetnik"></span>
849	        <div class="prazna-poraka"></div>
850	      </div>
851	      <div class="lenti">
852	        <div class="lenta"><i>Вода</i><span class="zica"><b class="b-voda"></b></span><u class="u-voda"></u></div>
853	        <div class="lenta"><i>Храна</i><span class="zica"><b class="b-hrana"></b></span><u class="u-hrana"></u></div>
854	        <div class="lenta"><i>Здравје</i><span class="zica"><b class="b-zdravje"></b></span><u class="u-zdravje"></u></div>
855	      </div>
856	      <div class="akcii"></div>`;
857	    kutija.appendChild(el);
858	    lejaJazli.push({
859	      koren:  el,
860	      faza:   el.querySelector(".leja-faza"),
