        // Влажен ден во просторијата — бара рачно проветрување
        if (!serija.vlazenDen &&
            Math.random() < KONFIG.SANSA_VLAZEN_DEN * klimaFaktor){
          serija.vlazenDen = true;
          izvesti(TEKST.vlazenDenPocna, "greska");
          susharaSePromeni = true;
        }
        // Мувла демнее додека влажноста е висока
        if (!serija.muvla && serija.vlaga > KONFIG.MUVLA_PRAG_VLAGA &&
            Math.random() < KONFIG.SANSA_MUVLA_DEN * klimaFaktor){
          serija.muvla = true;
          serija.imalaMuvla = true;
          izvesti(TEKST.muvlaNajdena, "greska");
          susharaSePromeni = true;
        }
        susharaSePromeni = true;
      }
      // Активната мувла јаде маса секој ден додека не се отстрани
      if (serija.muvla)
        serija.izgubenoMasa = Math.min(0.6, serija.izgubenoMasa + KONFIG.MUVLA_ZAGUBA_DEN * tempo);

    } else {  // faza === "zreenje"
      const prethoden = Math.floor(serija.denoviZreenje);
      serija.denoviZreenje += tempo;
      if (Math.floor(serija.denoviZreenje) !== prethoden){
        serija.burpDostapen = true;              // нов ден → нов бурп
        susharaSePromeni = true;
      }
    }
  }
  if (susharaSePromeni && aktivnoJazice === "sushara") panelValjaSe = true;"""),

