# ═══ 6. Точност од влажност при пакување (ја заменува старата по денови) ═══
("""/** Претвора поминати денови сушење во точност 0–1 (види §5 од спецификацијата). */
function tochnostOdSushenje(denovi, imaSushara){
  const d1 = imaSushara ? 8 : 9;      // прв идеален ден
  const d2 = imaSushara ? 14 : 12;    // последен идеален ден
  if (denovi <  d1)     return 0.55;  // предвреме
  if (denovi <= d2)     return 1.00;  // идеално
  if (denovi <= d2 + 4) return 0.80;  // прифатливо
  return 0.65;                        // пресушено
}""",
 """/**
 * Точност на сушењето од влажноста ВО МОМЕНТОТ НА ПАКУВАЊЕ во тегли.
 * Професионалната сушара го проширува идеалниот појас.
 */
function tochnostOdVlaga(vlaga, imaSushara){
  const idealMin = imaSushara ? 8 : 10;
  const idealMax = imaSushara ? 20 : 16;
  if (vlaga < idealMin - 3)  return 0.70;  // пресушено
  if (vlaga <= idealMax)     return 1.00;  // идеално
  if (vlaga <= idealMax + 9) return 0.85;  // уште влажно
  return 0.65;                             // премногу рано
}"""),

