  telo.innerHTML = `
    <div class="stavka">
      <div class="stavka-glava"><span class="stavka-ime">Прецизно подрежување</span></div>
      <div class="stavka-opis">Внимателно се отстранува вишокот лисја.
        −${Math.round((1 - KONFIG.TRIM_MASA) * 100)}% маса, но
        +${KONFIG.TRIM_KVALITET} квалитет на крајот.</div>
      <button onclick="oberi(${indeks}, true); zatvoriModal();">Подрежи прецизно</button>
    </div>
    <div class="stavka">
      <div class="stavka-glava"><span class="stavka-ime">Брзо кастрење</span></div>
      <div class="stavka-opis">Целата маса влегува во сушарата, без бонус.</div>
      <button onclick="oberi(${indeks}, false); zatvoriModal();">Кастри брзо</button>
    </div>`;
  document.getElementById("modal").classList.add("otvoren");
  zadnoFokusirano = document.activeElement;
  const prvoKopce = telo.querySelector("button");
  if (prvoKopce) prvoKopce.focus();
}

function oberi(indeks, precizno){
  const r = sostojba.lei[indeks].rastenie; if (!r || r.faza !== "ZRELO") return;
  const sorta = najdiSorta(r.sorta); if (!sorta) return;

  const prosekZdravje = r.brojTikovi > 0 ? r.zbirZdravje / r.brojTikovi : 0;
  const suvo   = presmetajPrinos(sorta, prosekZdravje, tekovnaLampa());
  const vlazno = (suvo / KONFIG.VLAZNO_VO_SUVO) * (precizno ? KONFIG.TRIM_MASA : 1);

  sostojba.sushara.push({
    id: sledenId++, sorta: r.sorta,
    gramaVlazno: vlazno, denovi: 0,
    faza: "sushenje", vlaga: KONFIG.VLAGA_START,
    potkrateno: !!precizno,
    vrtenja: 0, trebaVrtenje: false, vrtenjeRok: 0,
    sledenoVrtenje: KONFIG.VRTENJE_INTERVAL,
    muvla: false, imalaMuvla: false, izgubenoMasa: 0, vlazenDen: false,
    tochnostPakuvanje: 0, denoviZreenje: 0, burpovi: 0, burpDostapen: false,
    prosekZdravje, deoviSoStetnik: r.deoviSoStetnik
  });
  sostojba.lei[indeks].rastenie = null;
  sostojba.statistika.vkupnoBerbi++;

  izvesti(TEKST.berba(Math.round(vlazno), sorta.ime), "pari");
  // Само префрли на Сушара ако играчот сè уште не бил таму — берба на
  // друга леја не смее да го киднапира јазичето што играчот моментално
  // го гледа (пр. Надградби).
  if (!posetenoSushara){ aktivnoJazice = "sushara"; posetenoSushara = true; }
  panelValjaSe = true;
  iscrtajSe();
}

/* ── Алатки во сушарата ── */
function zavrti(serijaId){
  const s = sostojba.sushara.find(x => x.id === serijaId);
  if (!s || s.faza !== "sushenje" || !s.trebaVrtenje) return;
  s.trebaVrtenje = false;
  s.vrtenja++;
  izvesti(TEKST.zavrteno);
  panelValjaSe = true;
  iscrtajSe();
}

function provetri(serijaId){
  const s = sostojba.sushara.find(x => x.id === serijaId);
  if (!s || !s.vlazenDen) return;
  s.vlazenDen = false;
  izvesti(TEKST.provetreno);
  panelValjaSe = true;
  iscrtajSe();
}

function otstraniMuvla(serijaId){
  const s = sostojba.sushara.find(x => x.id === serijaId);
  if (!s || !s.muvla) return;
  const zrtva = s.gramaVlazno * KONFIG.MUVLA_TROSHOK_CISTENJE;
  s.izgubenoMasa = Math.min(0.6, s.izgubenoMasa + KONFIG.MUVLA_TROSHOK_CISTENJE);
  s.muvla = false;
  izvesti(TEKST.muvlaOtstraneta(Math.round(zrtva)));
  panelValjaSe = true;
  iscrtajSe();
}

function spakuvajVoTegli(serijaId){
  const s = sostojba.sushara.find(x => x.id === serijaId);
  if (!s || s.faza !== "sushenje") return;
  if (s.vlaga > KONFIG.VLAGA_PAKUVANJE_MAX){ izvesti(TEKST.ranoZaTegli, "greska"); return; }
  s.tochnostPakuvanje = tochnostOdVlaga(s.vlaga, sostojba.nadgradbi.sushara);
  s.faza = "zreenje";
  s.denoviZreenje = 0;
  s.burpovi = 0;
  s.burpDostapen = true;         // првиот бурп е достапен веднаш
  s.trebaVrtenje = false; s.vlazenDen = false; s.muvla = false;
  izvesti(TEKST.spakuvano(Math.round(s.vlaga)));
  panelValjaSe = true;
  iscrtajSe();
}

function burpni(serijaId){
  const s = sostojba.sushara.find(x => x.id === serijaId);
  if (!s || s.faza !== "zreenje" || !s.burpDostapen) return;
  s.burpDostapen = false;
  s.burpovi++;
  izvesti(TEKST.burpnato);
  panelValjaSe = true;
  iscrtajSe();
}"""),

# ═══ 8. zavrsiSushenje: важи само по зреењето; ги собира сите бонуси ═══
("""function zavrsiSushenje(serijaId){
  const idx = sostojba.sushara.findIndex(s => s.id === serijaId);
  if (idx === -1) return;
  const serija = sostojba.sushara[idx];
  const sorta = najdiSorta(serija.sorta); if (!sorta) return;

  const tochnost = tochnostOdSushenje(Math.floor(serija.denovi), sostojba.nadgradbi.sushara);
  const kvalitet = presmetajKvalitet(
    serija.prosekZdravje, tochnost, sorta.genetika,
    tekovnaLampa().kvalitetBonus, Math.floor(serija.deoviSoStetnik)
  );
  const ocenka = najdiOcenka(kvalitet);
  const grama  = serija.gramaVlazno * KONFIG.VLAZNO_VO_SUVO;""",
 """function zavrsiSushenje(serijaId){
  const idx = sostojba.sushara.findIndex(s => s.id === serijaId);
  if (idx === -1) return;
  const serija = sostojba.sushara[idx];
  const sorta = najdiSorta(serija.sorta); if (!sorta) return;
  if (serija.faza !== "zreenje"){ izvesti(TEKST.ranoZaTegli, "greska"); return; }
  if (serija.denoviZreenje < KONFIG.ZREENJE_MIN_DENOVI){
    izvesti(TEKST.ranoZaMagacin(KONFIG.ZREENJE_MIN_DENOVI), "greska"); return;
  }

  // Основата ја дава формулата за квалитет; негата во сушарата се
  // надградува врз неа: навремени вртења, редовни бурпови, прецизно
  // подрежување — а мувлата (дури и отстранета) остава трага.
  const osnova = presmetajKvalitet(
    serija.prosekZdravje, serija.tochnostPakuvanje, sorta.genetika,
    tekovnaLampa().kvalitetBonus, Math.floor(serija.deoviSoStetnik)
  );
  const negaBonus = serija.vrtenja * KONFIG.VRTENJE_BONUS
                  + Math.min(serija.burpovi, 6) * KONFIG.BURP_BONUS
                  + (serija.potkrateno ? KONFIG.TRIM_KVALITET : 0)
                  - (serija.imalaMuvla ? 4 : 0);
  const kvalitet = stegni(osnova + negaBonus, 0, 100);
  const ocenka = najdiOcenka(kvalitet);
  const grama  = serija.gramaVlazno * (1 - serija.izgubenoMasa) * KONFIG.VLAZNO_VO_SUVO;"""),

