  let html = `<div class="stavka"><div class="stavka-glava">
      <span class="stavka-ime">Берза денес</span></div><div class="stavka-opis">`;
  html += SORTI.filter(s => sostojba.nivo >= s.nivo).map(s => {
    const pazar = sostojba.pazar[s.id] || 1;
    return `${s.ime}: <b style="color:${pazar >= 1 ? "var(--zelena)" : "var(--crvena)"}">` +
           `${formatPari(s.cenaPoGram * pazar)} ден/г ${pazar >= 1 ? "▲" : "▼"}</b>`;
  }).join("<br>");
  html += `</div></div>`;

  if (!sostojba.magacin.length)
    return html + `<div class="prazno">Немаш производ за продажба.<br>Заврши зреење во сушарата.</div>`;

  html += sostojba.magacin.map(p => {
    const sorta = najdiSorta(p.sorta);
    const pazar = sostojba.pazar[p.sorta] || 1;
    const cena = cenaNaSerija(p);
    return `
    <div class="stavka">
      <div class="stavka-glava">
        <span class="stavka-ime">${sorta ? sorta.ime : "?"}</span>
        <span class="oznaka ${p.klasa}">${p.ocenka}</span>
      </div>
      <div class="stavka-opis">
        ${Math.round(p.grama)} г × ${formatPari((sorta ? sorta.cenaPoGram : 0) * pazar)} ден/г
        × ${p.ocenkaMult.toFixed(1)} (оценка)${p.testirano ? ` × ${KONFIG.BONUS_LABORATORIJA} (сертификат)` : ""}<br>
        Пазарот е ${pazar >= 1 ? "над" : "под"} просекот (${(pazar * 100).toFixed(0)}%) —
