  sellUnits(strainId, qty){
    const have = this.state.inventory[strainId]||0;
    qty = Math.min(qty, have);
    if (qty<=0) return;
    const strain = this.strainById(strainId);
    let total = 0;
    let boost = this.state.sellBoost ? {...this.state.sellBoost} : null;
    for (let i=0;i<qty;i++){
      let mult = this.sellPriceMult();
      if (boost && boost.remaining>0) { mult *= boost.mult; boost.remaining--; }
      total += strain.price*mult;
    }
    const inv = {...this.state.inventory, [strainId]: have-qty };
    const dayCounters = {...this.state.dayCounters, sold: this.state.dayCounters.sold+qty};
    this.setState({ inventory: inv, dayCounters, sellBoost: boost && boost.remaining>0 ? boost : null });
    this.addMoney(Math.round(total));
    this.sfx('click');
  }
