      else if (def.key === 'trader') {
        const fulfillable = this.state.orders.find(o => (this.state.inventory[o.strainId]||0) >= o.qty);
        if (fulfillable) this.fulfillOrder(fulfillable.id);
        else { const keys = Object.keys(this.state.inventory).filter(k=>this.state.inventory[k]>0); if (keys.length) this.sellUnits(keys[0], 1); }
