    while (picks.length<3 && pool.length) { const i = Math.floor(Math.random()*pool.length); picks.push(pool.splice(i,1)[0]); }
    const challenges = picks.map(tpl => { const goal = tpl.min + Math.floor(Math.random()*(tpl.max-tpl.min+1)); return { id: tpl.id, key: tpl.key, goal, rewardMoney: tpl.rewardMoney, rewardXp: tpl.rewardXp, labelMk: tpl.labelMk(goal), labelEn: tpl.labelEn(goal), done:false }; });
    this.setState({ challenges, dayCounters: { harvest:0, earned:0, water:0, feed:0, sold:0, orders:0 } });
  }
  checkChallenges(){
    const dc = this.state.dayCounters;
    let changed = false;
    const challenges = this.state.challenges.map(c => {
      if (c.done) return c;
      const progress = dc[c.key] || 0;
      if (progress >= c.goal) { changed = true; return {...c, done:true}; }
      return c;
    });
    if (changed) {
      this.setState({ challenges });
      challenges.forEach(c => { if (c.done && !c._claimed) { c._claimed = true; this.addMoney(c.rewardMoney); this.addXp(c.rewardXp); } });
    }
  }

  statValue(key){
    const s = this.state;
    if (key==='greenhouseUnlocked') return s.rooms.greenhouse && s.rooms.greenhouse.unlocked ? 1 : 0;
    if (key==='breedingLabUnlocked') return s.rooms.breeding_lab && s.rooms.breeding_lab.unlocked ? 1 : 0;
    if (key==='level') return s.level;
    if (key==='prestigeCount') return s.stats.prestigeCount;
    return s.stats[key] || 0;
  }
  checkAchievements(){
    const unlocked = new Set(this.state.achievementsUnlocked);
    const gained = [];
    this.data.ACHIEVEMENTS.forEach(a => { if (!unlocked.has(a.id) && this.statValue(a.statKey) >= a.value) { unlocked.add(a.id); gained.push(a); } });
    if (gained.length) {
      const xpGain = gained.reduce((sum,a)=>sum+a.rewardXp,0);
      const toasts = [...this.state.toasts];
      let nextId = this.state.nextToastId;
      gained.forEach(a => toasts.push({ id: nextId++, name: this.state.lang==='mk'?a.nameMk:a.nameEn }));
      this.setState({ achievementsUnlocked:[...unlocked], toasts, nextToastId: nextId });
      this.addXp(xpGain);
      this.sfx('achievement');
      toasts.forEach(ts => setTimeout(() => { this.setState({ toasts: this.state.toasts.filter(x=>x.id!==ts.id) }); }, 4200));
    }
    this.checkChallenges();
  }

  canPrestige(){ return this.state.level >= 10; }
  doRebirth(){
    if (!this.canPrestige()) return;
    const gained = Math.floor(this.state.level/2) + Math.floor(this.state.stats.lifetimeMoneyEarned/5000);
    const startMoney = this.props.startingMoney ?? 500;
    this.setState({
      money: startMoney, displayMoney: startMoney, xp:0, level:1, plants:[], inventory:{}, customStrains: this.state.customStrains,
      discoveredIds: [],
      rooms: { starter:{unlocked:true,lampTier:0}, greenhouse:{unlocked:false,lampTier:0}, breeding_lab:{unlocked:false} },
      staff: { waterer:false, feeder:false, harvester:false, trader:false },
      orders: [], activeRoomId:'starter',
      prestige: this.state.prestige+gained,
      stats: {...this.state.stats, prestigeCount: this.state.stats.prestigeCount+1},
      showRebirthConfirm: false,
    });
    this.sfx('levelup');
    this.scheduleAchCheck();
  }

  triggerRandomEvent(){
    const pool = this.data.EVENT_POOL;
    const ev = pool[Math.floor(Math.random()*pool.length)];
    this.setState({ activeEvent: ev, nextEventCheckIn: 100+Math.floor(Math.random()*80) });
  }
  resolveEventChoice(choice){
    if (choice.type==='money' || choice.type==='moneyRisk') { const amt = choice.min + Math.random()*(choice.max-choice.min); this.addMoney(Math.round(amt)); }
    else if (choice.type==='sellBoost') { this.setState({ sellBoost: { mult: choice.mult, remaining: choice.count } }); }
    else if (choice.type==='healthHit') {
      const dmg = choice.min + Math.random()*(choice.max-choice.min);
      const plants = this.state.plants;
      if (plants.length) { const idx = Math.floor(Math.random()*plants.length); const updated = plants.map((p,i)=> i===idx ? {...p, health: Math.max(0,p.health-dmg)} : p); this.setState({ plants: updated }); }
    }
    else if (choice.type==='freeSeed') {
      if (choice.cost>0) { if (this.state.money<choice.cost) { this.sfx('error'); this.setState({activeEvent:null}); return; } this.addMoney(-choice.cost); }
      const locked = this.allStrains().filter(s=>!this.state.discoveredIds.includes(s.id) && !s.hybrid ? this.state.level < s.unlockLevel : !this.state.discoveredIds.includes(s.id));
      if (locked.length) { const pick = locked[Math.floor(Math.random()*locked.length)]; this.setState({ discoveredIds:[...this.state.discoveredIds, pick.id] }); }
    }
    else if (choice.type==='sellAllBonus') {
      const s = this.state;
      let total = 0;
      Object.keys(s.inventory).forEach(id => { const strain = this.strainById(id); total += (s.inventory[id]||0)*strain.price*choice.mult*this.sellPriceMult(); });
      this.setState({ inventory:{} });
      this.addMoney(Math.round(total));
    }
    this.setState({ activeEvent:null });
    this.sfx('click');
  }

  tutNext(){
    if (this.state.tutorialStep >= 6) { this.setState({ showTutorial:false }); this.addMoney(300); }
    else this.setState({ tutorialStep: this.state.tutorialStep+1 });
    this.sfx('click');
  }
  tutSkip(){ this.setState({ showTutorial:false }); this.sfx('click'); }
  replayTutorial(){ this.setState({ showTutorial:true, tutorialStep:0 }); }

  tick(){
    if (!this.state.dataLoaded) return;
    const dt = 1;
    const decaySpeed = this.props.decaySpeed ?? 1;
    const plants = this.state.plants.map(p => {
      const strain = this.strainById(p.strainId);
      const lamp = this.lampTier(p.roomId);
      let water = Math.max(0, p.water - (100/45)*dt*decaySpeed);
      let food = Math.max(0, p.food - (100/75)*dt*decaySpeed);
      let health = p.health;
      if (water<20 || food<20) health = Math.max(0, health-1.5*dt);
      else if (water>50 && food>50) health = Math.min(100, health+0.8*dt);
      const stressMult = health<40 ? 0.5 : 1;
      const growSec = Math.max(20, strain.growSec*lamp.growMult);
      let progress = p.progress;
      if (water>0 && food>0) progress = Math.min(1, progress + (dt/growSec)*stressMult);
      return {...p, water, food, health, progress};
    });
    this.setState({ plants });

    this.staffAutomation(dt);

    const DAY_LEN = this.props.dayLengthSec ?? 120;
    let secIntoDay = this.state.secIntoDay + dt;
    if (secIntoDay >= DAY_LEN) {
      secIntoDay = 0;
      const day = this.state.day+1;
      const orders = this.state.orders.filter(o=>o.expiresAtDay>day);
      this.setState({ day, orders });
      this.rerollChallenges();
    }
    this.setState({ secIntoDay, stats: {...this.state.stats, playSeconds: this.state.stats.playSeconds+dt} });

    this.maybeGenerateOrder();

    const nextEventCheckIn = this.state.nextEventCheckIn - dt;
    if (nextEventCheckIn <= 0 && !this.state.activeEvent && !this.state.showTutorial) this.triggerRandomEvent();
    else this.setState({ nextEventCheckIn });

    this._saveAcc = (this._saveAcc||0)+dt;
    if (this._saveAcc >= 8) { this._saveAcc = 0; this.writeSave(); }
  }

  renderVals(){
    const s = this.state;
    if (!s.dataLoaded || !this.data) return { dataLoaded:false, notLoaded:true };
    const d = this.data;
    const t = d.STR[s.lang] || d.STR.mk;
    const lang = s.lang;
    const nm = (strain) => lang==='mk' ? strain.nameMk : strain.nameEn;

    const xpNeed = d.xpToNext(s.level);
    const xpPct = Math.max(2, Math.min(100, (s.displayXp/xpNeed)*100));
    const navDef = (id) => ({ bg: s.activeTab===id ? 'oklch(60% 0.11 152)' : 'transparent', color: s.activeTab===id ? '#ffffff' : 'oklch(45% 0.02 150)' });

    const DAY_LEN = this.props.dayLengthSec ?? 120;
    const gameHour = (s.secIntoDay/DAY_LEN)*24;
    const lightsOn = gameHour < 18;
    let ambSky, ambIconColor, ambLabel;
    if (lightsOn) { ambSky = 'linear-gradient(120deg,#2a1f3d 0%,#3d2350 45%,#4a2a3d 100%)'; ambIconColor = '#f9a8d4'; ambLabel = (lang==='mk'?'Светлосен циклус: ВКЛУЧЕН':'Light cycle: ON') + ' · ' + Math.floor(gameHour) + 'h'; }
    else { ambSky = 'linear-gradient(120deg,#0c1310 0%,#0a1512 60%,#0d1a14 100%)'; ambIconColor = '#4b5563'; ambLabel = (lang==='mk'?'Темен период':'Dark period') + ' · ' + Math.floor(gameHour) + 'h'; }

    const rooms = d.ROOM_TYPES.map(rd => {
      const rs = s.rooms[rd.id];
      const unlocked = rs && rs.unlocked;
      const active = s.activeRoomId===rd.id;
      return { id: rd.id, name: lang==='mk'?rd.nameMk:rd.nameEn, locked: !unlocked, unlockedFlag: !!unlocked, lockCostLabel: d.formatCompact(rd.unlockCost), capLabel: rd.isLab ? '—' : String(rd.capacity),
